    SkillHubBoundary("Browse this management profile’s configured skill sources. Searches and previews run on the Hermes host and can fetch remote bundles. Installation is a separate action.","浏览此管理配置的技能源。搜索和预览在 Hermes 主机上执行，可能获取远程技能包。安装是单独的操作。","Liúlǎn cǐ guǎnlǐ pèizhì de jìnéng yuán. Sōusuǒ hé yùlǎn zài Hermes zhǔjī shàng zhíxíng, kěnéng huòqǔ yuǎnchéng jìnéng bāo. Ānzhuāng shì dāndú de cāozuò."),
    SkillHubPreview("Preview bundle","预览技能包","Yùlǎn jìnéng bāo"),
    SkillHubPreviewEmpty("The host returned metadata without SKILL.md text.","主机返回了元数据，但没有 SKILL.md 文本。","Zhǔjī fǎnhuí le yuán shùjù, dàn méiyǒu SKILL.md wénběn."),
    SkillHubPreviewHelp("This is the host’s SKILL.md preview and file manifest. Opening it displays source text without running its instructions or installing files.","这是主机提供的 SKILL.md 预览和文件清单。打开仅显示源文本，不运行其中的指令，也不安装文件。","Zhè shì zhǔjī tígōng de SKILL.md yùlǎn hé wénjiàn qīngdān. Dǎkāi jǐn xiǎnshì yuán wénběn, bù yùnxíng qízhōng de zhǐlìng, yě bù ānzhuāng wénjiàn."),
    SkillHubInstalled("Host reports installed","主机报告已安装","Zhǔjī bàogào yǐ ānzhuāng"),
    SkillHubFiles("Bundle file names","技能包文件名","Jìnéng bāo wénjiàn míng"),
    SkillHubScan("Run host scan","运行主机扫描","Yùnxíng zhǔjī sǎomiáo"),
    SkillHubScanEffect("Hermes resolves the bundle into quarantine and runs its configured scanners. The optional Tier 1 scanner can take two minutes. Cancel stops waiting on this phone; host scanning may continue.","Hermes 将技能包解析到隔离区并运行已配置的扫描器。可选的一级扫描器可能需要两分钟。取消会停止手机等待；主机扫描可能继续。","Hermes jiāng jìnéng bāo jiěxī dào gélí qū bìng yùnxíng yǐ pèizhì de sǎomiáoqì. Kě xuǎn de yī jí sǎomiáoqì kěnéng xūyào liǎng fēnzhōng. Qǔxiāo huì tíngzhǐ shǒujī děngdài; zhǔjī sǎomiáo kěnéng jìxù."),
    SkillHubHostEvidence("Host-reported scan evidence. Tier 1 is advisory; incomplete checks leave missing evidence.","主机报告的扫描证据。一级扫描仅供参考；未完成的检查表示证据不完整。","Zhǔjī bàogào de sǎomiáo zhèngjù. Yī jí sǎomiáo jǐn gōng cānkǎo; wèi wánchéng de jiǎnchá biǎoshì zhèngjù bù wánzhěng."),
    SkillHubTrust("Reported trust level","报告的信任级别","Bàogào de xìnrèn jíbié"),
    SkillHubVerdict("Reported verdict","报告的结论","Bàogào de jiélùn"),
    SkillHubPolicy("Host install policy","主机安装策略","Zhǔjī ānzhuāng cèlüè"),
    SkillHubFindings("Core scan findings","核心扫描发现","Héxīn sǎomiáo fāxiàn"),
    SkillHubTier1("Optional Tier 1","可选一级扫描","Kě xuǎn yī jí sǎomiáo"),
    SkillHubTier1Passed("Host reports no failures among completed checks","主机报告已完成检查中没有失败","Zhǔjī bàogào yǐ wánchéng jiǎnchá zhōng méiyǒu shībài"),
    SkillHubTier1Findings("Host reports findings or failures","主机报告发现或失败","Zhǔjī bàogào fāxiàn huò shībài"),
    SkillHubTier1Unavailable("No Tier 1 result reported","未报告一级扫描结果","Wèi bàogào yī jí sǎomiáo jiéguǒ"),
    SkillHubIncomplete("Checks not completed","未完成的检查","Wèi wánchéng de jiǎnchá"),
    SkillHubSensitiveFinding("Sensitive finding; inspect its message on the Hermes host.","敏感发现；请在 Hermes 主机上查看消息。","Mǐngǎn fāxiàn; qǐng zài Hermes zhǔjī shàng chákàn xiāoxī."),
    SkillHubTimedOut("Some sources timed out; results may be incomplete.","部分来源超时；结果可能不完整。","Bùfèn láiyuán chāoshí; jiéguǒ kěnéng bù wánzhěng."),
    SkillHubSourceUnavailable("This source is unavailable, rate limited or included through the index. Choose another source.","此来源不可用、受速率限制或通过索引提供。请选择其他来源。","Cǐ láiyuán bù kěyòng, shòu sùlǜ xiànzhì huò tōngguò suǒyǐn tígōng. Qǐng xuǎnzé qítā láiyuán."),
    SkillHubSourcesUnavailable("Source details unavailable; all-source search remains selectable.","来源详情不可用；仍可选择所有来源搜索。","Láiyuán xiángqíng bù kěyòng; réng kě xuǎnzé suǒyǒu láiyuán sōusuǒ."),
    SkillHubIdentifierUnsupported("This identifier cannot use the supported native preview route. Use the Hermes dashboard.","此标识符无法使用支持的原生预览接口。请使用 Hermes 控制台。","Cǐ biāozhìfú wúfǎ shǐyòng zhīchí de yuánshēng yùlǎn jiēkǒu. Qǐng shǐyòng Hermes kòngzhìtái."),
    SkillHubSearchLimit("Shows at most 20 results per search; refine the query to find more.","每次搜索最多显示 20 条结果；可细化查询以查找更多。","Měi cì sōusuǒ zuìduō xiǎnshì èr shí tiáo jiéguǒ; kě xìhuà cháxún yǐ cházhǎo gèng duō."),
    SkillHubQueryInvalid("Enter 1–256 characters on one line.","请输入一行 1–256 个字符。","Qǐng shūrù yì háng yī dào èr bǎi wǔ shí liù gè zìfú."),
    SkillHubInvalid("The host returned unsupported or oversized Skill Hub data. Use the Hermes dashboard.","主机返回不支持或过大的技能中心数据。请使用 Hermes 控制台。","Zhǔjī fǎnhuí bù zhīchí huò guò dà de jìnéng zhōngxīn shùjù. Qǐng shǐyòng Hermes kòngzhìtái."),
    EndpointStageUrl("Stage returned address","暂存返回的地址","Zàncún fǎnhuí de dìzhǐ"),
    EndpointStageMode("Stage checked API mode","暂存已检查的 API 模式","Zàncún yǐ jiǎnchá de API móshì"),
    EndpointStageCatalog("Add returned models to draft","将返回的模型加入草稿","Jiāng fǎnhuí de móxíng jiārù cǎogǎo"),
    EndpointStageModel("Use this model in draft","在草稿中使用此模型","Zài cǎogǎo zhōng shǐyòng cǐ móxíng"),
    EndpointStageUnavailable("These values are missing, ambiguous, unsupported or too large to stage together. Choose an individual model or edit the draft.","这些值缺失、存在歧义、不受支持或过大，无法一起暂存。请选择单个模型或编辑草稿。","Zhèxiē zhí quēshī, cúnzài qíyì, bù shòu zhīchí huò guò dà, wúfǎ yìqǐ zàncún. Qǐng xuǎnzé dāngè móxíng huò biānjí cǎogǎo."),
    EndpointStageOnly("These actions update only your draft. Review and confirm Save separately.","此类操作只会更新草稿。请另行审阅并确认保存。","Cǐ lèi cāozuò zhǐ huì gēngxīn cǎogǎo. Qǐng lìngxíng shěnyuè bìng quèrèn bǎocún."),
    EndpointStageAlready("These values are already in the draft.","这些值已在草稿中。","Zhèxiē zhí yǐ zài cǎogǎo zhōng."),
    EndpointStageUrlEffect("Returned address staged. Any new key and imported metadata in this draft were cleared. Review the destination and credential choice before saving.","已暂存返回的地址。已清除此草稿中的新密钥和导入元数据。保存前请审阅目标地址和凭据选项。","Yǐ zàncún fǎnhuí de dìzhǐ. Yǐ qīngchú cǐ cǎogǎo zhōng de xīn mìyuè hé dǎorù yuánshùjù. Bǎocún qián qǐng shěnyuè mùbiāo dìzhǐ hé píngjù xuǎnxiàng."),
    EndpointMetadataDraft("Staged model metadata","已暂存的模型元数据","Yǐ zàncún de móxíng yuánshùjù"),
    EndpointMetadataClear("Clear staged metadata","清除暂存元数据","Qīngchú zàncún yuánshùjù"),
    EndpointMetadataCleared("Staged metadata cleared. Saved host metadata is unchanged.","已清除暂存元数据。主机上已保存的元数据未改变。","Yǐ qīngchú zàncún yuánshùjù. Zhǔjī shàng yǐ bǎocún de yuánshùjù wèi gǎibiàn."),
    EndpointMetadataKeep("Blank returned metadata keeps existing values. Clearing staged metadata does not remove saved aliases or reasoning settings.","返回的空元数据会保留现有值。清除暂存元数据不会删除已保存的别名或推理设置。","Fǎnhuí de kōng yuánshùjù huì bǎoliú xiànyǒu zhí. Qīngchú zàncún yuánshùjù bú huì shānchú yǐ bǎocún de biémíng huò tuīlǐ shèzhì."),
    EndpointMetadataUnsupported("Existing model or reasoning settings cannot be safely merged with this metadata. Clear the staged metadata or adjust the host configuration.","无法将此元数据与现有模型或推理设置安全合并。请清除暂存元数据或调整主机配置。","Wúfǎ jiāng cǐ yuánshùjù yǔ xiànyǒu móxíng huò tuīlǐ shèzhì ānquán hébìng. Qǐng qīngchú zàncún yuánshùjù huò tiáozhěng zhǔjī pèizhì."),
    EndpointAliasRedirect("Saved default model after alias resolution","解析别名后保存的默认模型","Jiěxī biémíng hòu bǎocún de mòrèn móxíng"),
    EndpointAliasGlobal("This save replaces the profile-wide reasoning preference for the canonical model. Other routes using that model are affected even when Make default is off.","此次保存会替换该配置中规范模型的共享推理偏好。即使未启用设为默认，使用该模型的其他路由也会受影响。","Cǐ cì bǎocún huì tìhuàn gāi pèizhì zhōng guīfàn móxíng de gòngxiǎng tuīlǐ piānhào. Jíshǐ wèi qǐyòng shè wéi mòrèn, shǐyòng gāi móxíng de qítā lùyóu yě huì shòu yǐngxiǎng."),
    EndpointAliasNoGlobal("This save does not write a shared reasoning preference.","此次保存不会写入共享推理偏好。","Cǐ cì bǎocún bú huì xiěrù gòngxiǎng tuīlǐ piānhào."),
    EndpointAliasManaged("Managed settings can omit the reasoning change. A save acknowledgement and observed settings do not prove runtime adoption.","托管设置可能会省略推理更改。保存确认及观察到的设置不代表运行时已采用。","Tuōguǎn shèzhì kěnéng huì shěnglüè tuīlǐ gēnggǎi. Bǎocún quèrèn jí guānchá dào de shèzhì bù dàibiǎo yùnxíngshí yǐ cǎiyòng."),
    EndpointAliasPrior("Current shared reasoning value","当前共享推理值","Dāngqián gòngxiǎng tuīlǐ zhí"),
    EndpointAliasNew("Requested shared reasoning value","请求的共享推理值","Qǐngqiú de gòngxiǎng tuīlǐ zhí"),
    EndpointAliasUnset("Not set","未设置","Wèi shèzhì"),
    Dismiss("Dismiss","关闭提示","Guānbì tíshì"), Loading("Loading…","正在加载…","Zhèngzài jiāzài…")
}
val LocalPreferences=staticCompositionLocalOf { AppPreferences() }
fun Words.localized(p: AppPreferences): String = buildList { add(en); if(p.chinese) { add(zh); if(p.pinyin) add(pin) } }.joinToString("\n")
@Composable fun label(w: Words) = w.localized(LocalPreferences.current)
fun statusWord(status: String) = when(status) {
    "response_failed" -> Words.ResponseFailed; "response_cancelled" -> Words.ResponseCancelled; "response_incomplete" -> Words.ResponseIncomplete
    "completed" -> Words.Completed; "failed" -> Words.Failed; "cancelled" -> Words.Cancelled; "interrupted" -> Words.Interrupted
    "response_submitted" -> Words.ResponseSubmitted; "incomplete" -> Words.Incomplete; "waiting_for_input" -> Words.WaitingInput; "unknown" -> Words.Unknown; "response_finished" -> Words.ResponseFinished; "waiting_for_approval" -> Words.Approval
    "running","submitting","queued" -> Words.Running; else -> Words.Chat
}
